import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("Claim Office", () => {
  describe("quote — edge cases", () => {
    it.todo("empty item list → premium 5 G (only the processing fee)");
    it.todo("unknown item type (broomstick) in quote → throws an error");
  });

  describe("quote — base premiums of main items (new customer: +10% first insurance, +5 G fee)", () => {
    it.todo("plain sword → 100 base + 10 first insurance + 5 fee = 115 G");
    it.todo("plain amulet → 60 base + 6 first insurance + 5 fee = 71 G");
    it.todo("plain staff → 80 base + 8 first insurance + 5 fee = 93 G");
    it.todo("plain potion → 40 base + 4 first insurance + 5 fee = 49 G");
  });

  describe("quote — components and building blocks", () => {
    it.todo("2 runes → 50 G base premium → 50 + 5 + 5 = 60 G");
    it.todo("3 runes → 60 G base premium (block) → 60 + 6 + 5 = 71 G");
    it.todo("4 runes → 100 G base premium (no block) → 100 + 10 + 5 = 115 G");
    it.todo("7 runes → 175 G base premium → 175 + 17.5 + 5 = 197.5 → rounded up to 198 G");
    it.todo("2 runes + 1 moonstone → 75 G base premium (different types, no block) → 75 + 7.5 + 5 = 87.5 → 88 G");
    it.todo("3 runes + 3 moonstones → 120 G base premium (two blocks) → 120 + 12 + 5 = 137 G");
  });

  describe("quote — item-specific modifiers", () => {
    it.todo("cursed sword (steel, enchantment 3), newcomer → 100 + 50 curse + 10 first + 5 fee = 165 G");
    it.todo("sword with exactly enchantment 5 → high-enchantment surcharge: 100 + 30 + 10 + 5 = 145 G");
    it.todo("sword with enchantment 4 → no high-enchantment surcharge: 115 G");
    it.todo("cursed sword with enchantment 5 → both surcharges: 100 + 50 + 30 + 10 + 5 = 195 G");
    it.todo("cursed sword with enchantment 4 → only curse surcharge: 165 G");
    it.todo("cursed sword + plain amulet → curse applies to sword only: 160 + 50 + 16 first + 5 fee = 231 G");
  });

  describe("quote — policy-wide modifiers", () => {
    it.todo("customer with exactly 2 years → loyalty discount: 100 − 20 + 10 + 5 = 95 G");
    it.todo("customer with 1 year → no loyalty discount: 115 G");
    it.todo("second quote in the scenario gets 15% follow-up discount: sword 100 + 10 − 15 + 5 = 100 G");
    it.todo("long-standing customer's second contract, cursed sword enchantment 7 → 160 G");
    it.todo("premium fraction is rounded up in MHPCO's favor: second quote of 2 runes 50 + 5 − 7.5 + 5 = 52.5 → 53 G");
  });

  describe("claim — standard reimbursement", () => {
    it.todo("regular sword (steel, enchantment 3), damage 500 → payout 400, remainingCap 1600");
    it.todo("rune damage 200 → payout 100 (no enchantment or material)");
    it.todo("dragon attack damages sword (500) and amulet (300) → payout 600 (deductible per damaged item)");
  });

  describe("claim — special clauses", () => {
    it.todo("steel sword enchantment 9, damage 1000 → payout 400 (50% then deductible)");
    it.todo("dragon-material sword enchantment 9, damage 1000 → payout 400 (50% rule wins)");
    it.todo("dragon-material sword enchantment 5, damage 800 → payout 700 (full reimbursement)");
    it.todo("dragon-material sword exactly enchantment 8, damage 1000 → payout 400");
    it.todo("payout fraction is rounded down in MHPCO's favor: enchantment 9 sword, damage 901 → 350.5 → 350");
  });

  describe("claim — cap", () => {
    it.todo("sword + amulet policy → insurance sum 1600, cap 3200: remainingCap after 500 sword damage = 2800");
    it.todo("cursed sword → cap 2000 based on unmodified insurance value");
    it.todo("sword + 3 runes (block) → insurance sum 1750, cap 3500");
    it.todo("two successive 1500 claims on a sword → payouts 1400 (remaining 600) then 600 (remaining 0)");
    it.todo("two swords → insurance sum 2000, cap 4000; both damaged, each damage has its own deductible");
  });

  describe("claim — errors", () => {
    it.todo("damage for an item type not in the policy → throws an error");
    it.todo("damage for an unknown item type → throws an error");
    it.todo("more damage entries of a type than items insured → throws an error");
    it.todo("negative damage amount → throws an error");
  });

  describe("CLI", () => {
    it.todo("reads the schema example scenario from stdin and writes results JSON to stdout");
    it.todo("exits non-zero and writes an error to stderr (no stdout results) for an unknown item type");
  });
});

