export interface Item {
  type: string;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: QuoteStep[];
}

export interface ScenarioResult {
  results: { premium: number }[];
}

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const basePremiumOf = (item: Item): number => {
  if (!Object.hasOwn(BASE_PREMIUMS, item.type)) throw new Error(`Unknown item type: ${item.type}`);
  return BASE_PREMIUMS[item.type];
};

const COMPONENT_TYPES = ["rune", "moonstone"];
const BLOCK_SIZE = 3;
const BLOCK_PREMIUM = 60;

const isComponent = (item: Item): boolean => COMPONENT_TYPES.includes(item.type);

const componentGroupPremium = (type: string, count: number): number =>
  count === BLOCK_SIZE ? BLOCK_PREMIUM : count * BASE_PREMIUMS[type];

const sum = (values: number[]): number => values.reduce((total, value) => total + value, 0);

const countOfType = (items: Item[], type: string): number => items.filter((item) => item.type === type).length;

const mainItemsPremium = (items: Item[]): number =>
  sum(items.filter((item) => !isComponent(item)).map(basePremiumOf));

const componentsPremium = (items: Item[]): number =>
  sum(COMPONENT_TYPES.map((type) => componentGroupPremium(type, countOfType(items, type))));

const totalBasePremium = (items: Item[]): number => mainItemsPremium(items) + componentsPremium(items);

const quotePremium = (items: Item[]): number => {
  const basePremium = totalBasePremium(items);
  const firstInsuranceSurcharge = (basePremium * FIRST_INSURANCE_SURCHARGE_PERCENT) / 100;
  return Math.ceil(basePremium + firstInsuranceSurcharge + PROCESSING_FEE);
};

export const runScenario = (scenario: Scenario): ScenarioResult => {
  const [quoteStep] = scenario.steps;
  return { results: [{ premium: quotePremium(quoteStep.items) }] };
};

