const LOYALTY_YEARS = 2;
const LOYALTY_DISCOUNT_PERCENT = 20;

const isLoyalCustomer = (yearsWithMHPCO: number): boolean => yearsWithMHPCO >= LOYALTY_YEARS;

const discountPercent = (yearsWithMHPCO: number): number =>
  isLoyalCustomer(yearsWithMHPCO) ? LOYALTY_DISCOUNT_PERCENT : 0;

const quotePremium = (items: Item[], yearsWithMHPCO: number): number => {
  const policyBase = policyBasePremium(items);
  const firstInsuranceSurcharge = percentOf(policyBase, FIRST_INSURANCE_SURCHARGE_PERCENT);
  const discount = percentOf(policyBase, discountPercent(yearsWithMHPCO));
  return Math.ceil(policyBase + itemRiskSurcharges(items) + firstInsuranceSurcharge - discount + PROCESSING_FEE);
};

export const runScenario = (scenario: Scenario): ScenarioResult => {
  const [quoteStep] = scenario.steps;
  return { results: [{ premium: quotePremium(quoteStep.items, scenario.customer.yearsWithMHPCO) }] };
};

