start=s.index('const processClaim')
s=s[:start]+'''const processClaim = (step: ClaimStep, policy: QuoteStep, alreadyPaid: number): ClaimResult => {
  const availableCap = policyCap(policy.items) - alreadyPaid;
  const payout = Math.min(claimPayout(step.incident.damages, policy), availableCap);
  return { payout, remainingCap: availableCap - payout };
};

const processQuote = (step: QuoteStep, yearsWithMHPCO: number, isFollowUp: boolean): QuoteResult => ({
  premium: quotePremium(step.items, yearsWithMHPCO, isFollowUp),
});

export const runScenario = (scenario: Scenario): ScenarioResult => {
  const paidPerPolicy = new Map<number, number>();
  return {
    results: scenario.steps.map((step, index) => {
      if (step.op === "quote") {
        return processQuote(step, scenario.customer.yearsWithMHPCO, isFollowUpContract(index));
      }
      const alreadyPaid = paidPerPolicy.get(step.policy) ?? 0;
      const result = processClaim(step, scenario.steps[step.policy] as QuoteStep, alreadyPaid);
      paidPerPolicy.set(step.policy, alreadyPaid + result.payout);
      return result;
    }),
  };
};
'''
